'use client';

import React, { useMemo, useRef, useState } from 'react';
import { ChevronDown, ChevronUp, RotateCcw, Search, Shapes, Upload, X } from 'lucide-react';
import type { CDMOPage } from '@/data/cdmoData';
import { ICON_LIBRARY, iconFromRef, itemIconKey, isImageIconRef } from '@/components/icons/SiteIcon';
import { getCapabilityIcon } from '@/components/icons/CapabilityIcons';
import { parseFacilityListParagraph } from '@/lib/facilityList';
// Generated by `node scripts/cms_icons_e2e.mjs --usage-out src/data/cmsIconUsage.json`:
// which items actually show an icon on each page.
import cmsIconUsage from '@/data/cmsIconUsage.json';

type IconUsage = Record<string, { shown: string[]; checked: string[] }>;
const ICON_USAGE = cmsIconUsage as IconUsage;

interface IconGroup {
  title: string;
  items: string[];
}

/** Every piece of text on the page that is shown with an icon, grouped as the page shows them. */
function collectIconItems(page: CDMOPage): IconGroup[] {
  const groups: IconGroup[] = [];
  const usage = ICON_USAGE[`${page.category}/${page.slug}`];
  // Only items the page shows with an icon (items added since the last check are listed too)
  const hasIcon = (text: string) => !usage || usage.shown.includes(text) || !usage.checked.includes(text);
  const add = (title: string, items: (string | undefined | null)[] | undefined) => {
    const clean = (items || []).map((t) => itemIconKey(t || '')).filter((t) => t && hasIcon(t));
    if (clean.length) groups.push({ title, items: Array.from(new Set(clean)) });
  };

  add('Capabilities', page.capabilities);
  add('Bioassay capabilities', page.bioassayCapabilities);
  add('Immunogenicity capabilities', page.immunogenicityCapabilities);
  add(
    'Analytical technologies',
    (page.analyticalTechnologies || []).map((t) => (typeof t === 'string' ? t : t?.name))
  );
  add('Applicable modalities', (page.applicableModalities || []).map((m) => m?.title));

  (page.sections || []).forEach((sec, idx) => {
    const name = sec.title?.trim() || `Section ${idx + 1}`;
    const listsInText = (sec.text || '')
      .split('\n\n')
      .map((para) => parseFacilityListParagraph(para)?.items || [])
      .flat();
    add(`${name}: section heading`, sec.title ? [sec.title, sec.secondaryTitle] : []);
    add(`${name}: points`, [...(sec.bullets || []), ...listsInText]);
    add(`${name}: cards`, (sec.cards || []).flatMap((c) => [c?.title, ...(c?.items || []).map((i) => i?.name)]));
    add(`${name}: steps`, (sec.steps || []).map((s) => s?.title));
  });
  return groups;
}

interface IconPickerPanelProps {
  page: CDMOPage;
  onChange: (itemIcons: Record<string, string>) => void;
  onUploadFile: (file: File, done: (url: string) => void) => void;
  uploading?: boolean;
  order?: number;
  sectionNumber?: number;
}

/**
 * "Icons on this page": lets an editor replace the icon of any point, card, step or heading with
 * one of the site's drawn icons, a general icon, or an uploaded SVG. Choices are stored in
 * `page.itemIcons` and show on the live page (and in the live preview) right away.
 */
export default function IconPickerPanel({ page, onChange, onUploadFile, uploading, order, sectionNumber }: IconPickerPanelProps) {
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const fileRef = useRef<HTMLInputElement>(null);

  const groups = useMemo(() => collectIconItems(page), [page]);
  const itemIcons = page.itemIcons || {};
  const total = groups.reduce((n, g) => n + g.items.length, 0);
  const chosenCount = groups.reduce((n, g) => n + g.items.filter((t) => itemIcons[t]).length, 0);

  const filtered = ICON_LIBRARY.filter((entry) => !query.trim() || entry.label.toLowerCase().includes(query.trim().toLowerCase()));

  const setIcon = (text: string, ref: string | null) => {
    const next = { ...itemIcons };
    if (ref) next[text] = ref;
    else delete next[text];
    onChange(next);
  };

  if (total === 0) return null;

  return (
    <div style={order !== undefined ? { order } : undefined} className="bg-white rounded-2xl border border-slate-200/90 shadow-sm overflow-hidden">
      <div
        onClick={() => setOpen(!open)}
        className="p-5 sm:p-6 flex items-center justify-between gap-4 bg-gradient-to-r from-slate-50 via-sky-50/30 to-slate-50 border-b border-slate-200 cursor-pointer hover:bg-slate-100/80 transition-colors select-none"
      >
        <div className="flex items-center gap-3.5 min-w-0">
          <div className="w-10 h-10 rounded-xl bg-brand-blue/10 border border-brand-blue/20 flex items-center justify-center text-brand-blue shrink-0">
            <Shapes className="w-5 h-5" />
          </div>
          <div className="min-w-0">
            <div className="flex items-center gap-2 flex-wrap mb-0.5">
              <span className="text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-md bg-brand-blue text-white shadow-2xs">
                {sectionNumber ? `Section ${sectionNumber} • ` : ''}Icons
              </span>
              <span className="text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-md bg-slate-200/80 text-slate-700">
                {chosenCount} of {total} customised
              </span>
            </div>
            <h3 className="text-base sm:text-lg font-bold text-neutral-900 truncate">
              {sectionNumber ? `${sectionNumber}. ` : ''}Icons on This Page
            </h3>
          </div>
        </div>
        <div className="flex items-center gap-3 shrink-0">
          <span className="text-xs text-slate-500 hidden sm:inline">{open ? 'Click to collapse' : 'Click to change icons'}</span>
          <div className="w-8 h-8 rounded-lg bg-white border border-slate-200 flex items-center justify-center text-slate-600 shadow-2xs">
            {open ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
          </div>
        </div>
      </div>

      {open && (
        <div className="p-6 sm:p-8 space-y-7">
          <p className="text-xs text-slate-600 leading-relaxed p-4 rounded-xl bg-sky-50/60 border border-sky-200/80">
            <span className="font-bold text-slate-900">Change the icon of any point, card or step. </span>
            &quot;Automatic&quot; keeps the icon the page picks on its own. Pick one of the site&apos;s drawn icons, a general icon,
            or upload your own SVG. The live preview updates as you choose; publish to make it live.
          </p>

          {groups.map((group) => (
            <div key={group.title} className="space-y-2.5">
              <h4 className="text-[11px] font-bold uppercase tracking-wider text-slate-800">{group.title}</h4>
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-2.5">
                {group.items.map((text) => {
                  const ref = itemIcons[text];
                  const Chosen = iconFromRef(ref);
                  const Auto = getCapabilityIcon(text);
                  const isEditing = editing === `${group.title}::${text}`;
                  return (
                    <div key={text} className={`rounded-xl border ${isEditing ? 'border-brand-blue ring-2 ring-brand-blue/15 lg:col-span-2' : 'border-slate-200'} bg-slate-50/60`}>
                      <div className="flex items-center gap-3 p-2.5">
                        <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 ${Chosen ? 'bg-brand-blue/10 border border-brand-blue/30 text-brand-blue' : 'bg-white border border-dashed border-slate-300 text-slate-400'}`}>
                          {Chosen ? <Chosen className="w-5 h-5" /> : Auto ? <Auto className="w-5 h-5" /> : <span className="text-[9px] font-bold uppercase">Auto</span>}
                        </div>
                        <div className="min-w-0 flex-1">
                          <p className="text-sm text-neutral-900 leading-snug truncate" title={text}>{text}</p>
                          <p className="text-[11px] text-slate-500">
                            {ref ? (isImageIconRef(ref) ? 'Uploaded icon' : 'Chosen icon') : 'Automatic (as the page picks it)'}
                          </p>
                        </div>
                        <button
                          type="button"
                          onClick={() => { setEditing(isEditing ? null : `${group.title}::${text}`); setQuery(''); }}
                          className="px-3 py-1.5 rounded-lg text-xs font-semibold border border-slate-300 bg-white hover:border-brand-blue hover:text-brand-blue cursor-pointer"
                        >
                          {isEditing ? 'Done' : 'Change'}
                        </button>
                        {ref && (
                          <button
                            type="button"
                            title="Back to automatic"
                            onClick={() => setIcon(text, null)}
                            className="p-1.5 rounded-lg text-slate-500 hover:text-brand-blue hover:bg-white cursor-pointer"
                          >
                            <RotateCcw className="w-4 h-4" />
                          </button>
                        )}
                      </div>

                      {isEditing && (
                        <div className="border-t border-slate-200 p-3 space-y-3 bg-white rounded-b-xl">
                          <div className="flex flex-wrap items-center gap-2">
                            <div className="relative flex-1 min-w-[200px]">
                              <Search className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                              <input
                                type="text"
                                value={query}
                                onChange={(e) => setQuery(e.target.value)}
                                placeholder="Search icons (vial, bioreactor, antibody…)"
                                className="w-full pl-9 pr-3 py-2 text-sm border border-slate-300 rounded-lg focus:outline-none focus:border-brand-blue"
                              />
                            </div>
                            <button
                              type="button"
                              disabled={uploading}
                              onClick={() => fileRef.current?.click()}
                              className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg bg-brand-orange text-white text-xs font-semibold hover:bg-brand-orange-hover disabled:opacity-60 cursor-pointer"
                            >
                              <Upload className="w-3.5 h-3.5" />
                              <span>{uploading ? 'Uploading…' : 'Upload SVG'}</span>
                            </button>
                            <input
                              ref={fileRef}
                              type="file"
                              accept=".svg,image/svg+xml,image/png,image/webp"
                              className="hidden"
                              onChange={(e) => {
                                const file = e.target.files?.[0];
                                if (file) onUploadFile(file, (url) => setIcon(text, url));
                                e.target.value = '';
                              }}
                            />
                            {ref && (
                              <button type="button" onClick={() => setIcon(text, null)} className="inline-flex items-center gap-1 px-3 py-2 rounded-lg border border-slate-300 text-xs font-semibold text-slate-700 hover:bg-slate-50 cursor-pointer">
                                <X className="w-3.5 h-3.5" />
                                <span>Use automatic</span>
                              </button>
                            )}
                          </div>
                          {(['Biologics & lab (drawn for this site)', 'General'] as const).map((section) => {
                            const entries = filtered.filter((e) => e.group === section);
                            if (!entries.length) return null;
                            return (
                              <div key={section}>
                                <p className="text-[10px] font-bold uppercase tracking-wider text-slate-500 mb-1.5">{section}</p>
                                <div className="grid grid-cols-6 sm:grid-cols-9 md:grid-cols-12 gap-1.5 max-h-56 overflow-y-auto pr-1">
                                  {entries.map(({ ref: entryRef, label, Icon }) => (
                                    <button
                                      key={entryRef}
                                      type="button"
                                      title={label}
                                      onClick={() => setIcon(text, entryRef)}
                                      className={`aspect-square rounded-lg border flex items-center justify-center cursor-pointer transition-colors ${ref === entryRef ? 'border-brand-blue bg-brand-blue/10 text-brand-blue' : 'border-slate-200 text-slate-700 hover:border-brand-blue hover:text-brand-blue'}`}
                                    >
                                      <Icon className="w-5 h-5" />
                                    </button>
                                  ))}
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
